const fs = require('node:fs/promises');
const path = require('node:path');
const { randomUUID } = require('node:crypto');
const sharp = require('sharp');

const imagesDirectory = path.join(
  __dirname,
  '../../storage/certificate-images'
);

const allowedFormats = new Set([
  'jpeg',
  'png',
  'webp',
]);

const getCertificateImagePath = (filename) => {
  // Accept only filenames generated by this service.
  if (
    typeof filename !== 'string' ||
    !/^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}\.webp$/.test(
      filename
    )
  ) {
    throw new Error('Invalid certificate image filename');
  }

  return path.join(imagesDirectory, filename);
};

const saveCertificateImage = async (buffer) => {
  let processedImage;

  try {
    const image = sharp(buffer, {
      limitInputPixels: 25_000_000,
      failOn: 'warning',
    });

    const metadata = await image.metadata();

    if (
      !allowedFormats.has(metadata.format) ||
      (metadata.pages ?? 1) > 1
    ) {
      throw new Error('Unsupported image format');
    }

    processedImage = await image
      .rotate()
      .resize({
        width: 2400,
        height: 2400,
        fit: 'inside',
        withoutEnlargement: true,
      })
      .webp({ quality: 90 })
      .toBuffer();
  } catch (_) {
    const error = new Error(
      'Upload a valid, non-animated JPEG, PNG or WebP image up to 25 megapixels'
    );

    error.code = 'INVALID_CERTIFICATE_IMAGE';
    throw error;
  }

  await fs.mkdir(imagesDirectory, {
    recursive: true,
  });

  const filename = `${randomUUID()}.webp`;
  const imagePath = getCertificateImagePath(filename);

  try {
    await fs.writeFile(imagePath, processedImage, {
      flag: 'wx',
    });
  } catch (error) {
    // Remove any partial file created by a failed write.
    if (error.code !== 'EEXIST') {
      await fs.unlink(imagePath).catch(() => {});
    }

    throw error;
  }

  return filename;
};

const deleteCertificateImage = async (filename) => {
  if (!filename) return;

  try {
    await fs.unlink(getCertificateImagePath(filename));
  } catch (error) {
    if (error.code !== 'ENOENT') {
      throw error;
    }
  }
};

module.exports = {
  saveCertificateImage,
  deleteCertificateImage,
  getCertificateImagePath,
};